CREATE TABLE workspace_revisions (name TEXT PRIMARY KEY, generation INTEGER NOT NULL DEFAULT 0);
INSERT INTO workspace_revisions (name) VALUES ('organizations');
CREATE TRIGGER revision_organizations_insert AFTER INSERT ON organizations BEGIN UPDATE workspace_revisions SET generation=generation+1 WHERE name='organizations'; END;
CREATE TRIGGER revision_organizations_update AFTER UPDATE ON organizations BEGIN UPDATE workspace_revisions SET generation=generation+1 WHERE name='organizations'; END;
CREATE TRIGGER revision_organizations_delete AFTER DELETE ON organizations BEGIN UPDATE workspace_revisions SET generation=generation+1 WHERE name='organizations'; END;
