CREATE INDEX IF NOT EXISTS messages_time_page ON messages(created_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS memberships_group_role ON memberships(household_id,role,user_id);
CREATE INDEX IF NOT EXISTS assignments_group_id ON assignments(household_id,id);
CREATE INDEX IF NOT EXISTS submissions_assignment_learner ON submissions(assignment_id,learner_id);
CREATE INDEX IF NOT EXISTS organization_memberships_org_user ON organization_memberships(organization_id,user_id,role);
CREATE INDEX IF NOT EXISTS applications_org_id ON applications(organization_id,id);
CREATE INDEX IF NOT EXISTS bookings_org_id ON bookings(organization_id,id);
CREATE TABLE profile_avatars (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, data_url TEXT NOT NULL);
INSERT INTO profile_avatars SELECT id,avatar FROM users WHERE avatar LIKE 'data:image/%';
UPDATE users SET avatar='avatar:stored' WHERE avatar LIKE 'data:image/%';
